package app.pockettavern.domain

import java.util.UUID

fun newId(): String = UUID.randomUUID().toString()
data class ProviderConfig(val id: String = newId(), val name: String = "Venice", val kind: String = "venice", val baseUrl: String = "https://api.venice.ai/api/v1", val models: List<ModelInfo> = emptyList(), val refreshedAt: Long = 0)
data class ModelInfo(val id: String = "", val name: String = "", val type: String = "text", val contextTokens: Int = 32768, val supportsTools: Boolean = false, val supportsVision: Boolean = false, val supportsReasoning: Boolean = false, val offline: Boolean = false, val rawJson: String = "{}")
data class Attachment(val id: String = newId(), val name: String = "", val mime: String = "", val path: String = "", val dataUrl: String = "")
data class Message(val id: String = newId(), val role: String = "user", val content: String = "", val reasoning: String = "", val toolCallsJson: String = "[]", val toolCallId: String = "", val status: String = "complete", val createdAt: Long = System.currentTimeMillis(), val attachments: List<Attachment> = emptyList())
data class Summary(val id: String = newId(), val text: String = "", val throughMessageId: String = "", val sourceHash: String = "", val createdAt: Long = System.currentTimeMillis(), val modelId: String = "")
data class Chat(val id: String = newId(), val title: String = "新会话", val providerId: String = "venice", val modelId: String = "", val presetId: String = "default", val characterId: String = "", val messages: List<Message> = emptyList(), val summaries: List<Summary> = emptyList(), val activeSummaryId: String = "", val skillIds: List<String> = emptyList(), val updatedAt: Long = System.currentTimeMillis())
data class Preset(val id: String = newId(), val name: String = "新预设", val systemPrompt: String = "", val temperature: Double = 0.8, val maxOutput: Int = 2048, val summaryPrompt: String = "用中文准确总结已有对话中的人物、事实、约定、未解决事项和当前进度。保留关键细节，不添加推测或新事实。", val summaryProviderId: String = "", val summaryModelId: String = "")
data class Character(val id: String = newId(), val name: String = "", val description: String = "", val personality: String = "", val scenario: String = "", val firstMessage: String = "", val examples: String = "", val systemPrompt: String = "", val userPersona: String = "", val originalJson: String = "")
data class Memory(val id: String = newId(), val text: String = "", val scope: String = "chat", val targetId: String = "", val enabled: Boolean = true, val locked: Boolean = false, val sourceMessageId: String = "", val updatedAt: Long = System.currentTimeMillis())
data class WorldEntry(val id: String = newId(), val name: String = "", val content: String = "", val keywords: List<String> = emptyList(), val always: Boolean = false, val enabled: Boolean = true, val characterId: String = "", val priority: Int = 0)
data class SkillRecord(val id: String = newId(), val name: String = "", val description: String = "", val content: String = "", val files: Map<String,String> = emptyMap(), val enabled: Boolean = true, val permissions: List<String> = emptyList(), val source: String = "本地导入", val warnings: List<String> = emptyList())
data class MediaJob(val id: String = newId(), val providerId: String = "", val modelId: String = "", val type: String = "", val requestJson: String = "{}", val queueId: String = "", val status: String = "", val resultJson: String = "", val filePath: String = "", val createdAt: Long = System.currentTimeMillis())
data class AppSettings(val autoCompress: Boolean = true, val compressionThreshold: Double = 0.8, val keepRecentTurns: Int = 8, val contextOverride: Int = 0, val darkMode: String = "system", val userPersona: String = "", val maxToolSteps: Int = 8)
data class AppData(val schemaVersion: Int = 1, val providers: List<ProviderConfig> = listOf(ProviderConfig(id="venice")), val chats: List<Chat> = emptyList(), val presets: List<Preset> = listOf(Preset(id="default",name="通用助手",systemPrompt="请用中文回答，遵循用户要求。准确区分事实与推测。"), Preset(id="roleplay",name="角色扮演",systemPrompt="遵循角色卡、世界设定和已发生的事实。用户控制自己的角色，不代替用户决定动作、台词、心理或选择。")), val characters: List<Character> = emptyList(), val memories: List<Memory> = emptyList(), val worldEntries: List<WorldEntry> = emptyList(), val skills: List<SkillRecord> = emptyList(), val mediaJobs: List<MediaJob> = emptyList(), val settings: AppSettings = AppSettings())
data class UiSession(val data: AppData = AppData(), val selectedChatId: String = "", val busy: Boolean = false, val loading: Boolean = true, val status: String = "", val contextPreview: String = "", val hasKeys: Set<String> = emptySet(), val pendingAttachments: List<Attachment> = emptyList())
data class CompletionResult(val content: String = "", val reasoning: String = "", val toolCallsJson: String = "[]", val rawJson: String = "{}")
data class StreamDelta(val content: String = "", val reasoning: String = "")
data class ContextBuild(val messagesJson: String, val estimatedTokens: Int, val budget: Int, val needsCompression: Boolean, val preview: String)
data class CompressionSlice(val messages: List<Message>, val throughMessageId: String, val sourceHash: String)
